import re
import logging
from taf.sw.nrdim.nrdim_params import NrdimParams
from taf.sw.nrdim.nrdim_request import NrdimRequest
from taf.sw.nrdim.convertor import NrdimConvertor


class NrdimCalculator(object):

    def __init__(self, specified_nrdim_params, url):
        self._nrdim_params = NrdimParams(specified_nrdim_params)
        self._nrdim_request = NrdimRequest(url)

        self._nrdim_convertor = None

    def convert_scf_to_nrdim_params(self, scf_file_path, cell_distname, cellgroup_distname, scf_mediation):
        if not scf_file_path:
            logging.warning("not specified SCF file, will use default nrdim parameters")
            return

        if not scf_mediation:
            scf_mediation = self._nrdim_request.request_scf_mediation_data()

        self._nrdim_convertor = NrdimConvertor(scf_file_path=scf_file_path,
                                               nrdim_params=self._nrdim_params,
                                               scf_mediation=scf_mediation,
                                               cell_distname=cell_distname,
                                               cellgroup_distname=cellgroup_distname)
        self._nrdim_params = self._nrdim_convertor.convert()

    def set_parameter(self, name, value):
        self._nrdim_params.set_parameter(name, value)

    def get_parameter(self, name):
        if not name:
            return self._nrdim_params.to_dict()
        return self._nrdim_params.get_parameter(name)

    def calculate_throughput(self, **kwargs):
        result = self._get_calculated_result(**kwargs)
        result = str(result)
        return self._extract_throughput(result)

    def _extract_throughput(self, result):
        logging.debug("calculated throughput response={}".format(result))
        downlink_throughput = re.search(r"DL tput: ([\d.]*)Mbps", result).group(1)
        uplink_throughput = re.search(r"UL tput: ([\d.]*)Mbps", result).group(1)
        return {"downlink": float(downlink_throughput), "uplink": float(uplink_throughput)}

    def _get_calculated_result(self):
        gnb_params = self._nrdim_params.to_dict()
        logging.info("starting to calculate throughput...")
        self._nrdim_params.pprint()
        return self._nrdim_request.get_throughput(gnb_params)
